// chain syntax — lazy pipeline
var bigOnes = arr.Where(Function(x) { return x > 5; })
                 .OrderByDescending(Function(x) { return x; })
                 .Take(10)
                 .ToArray();

// aggregations with lambda selector
var total = arr.Sum();
var avgK  = arr.Average(Function(x) { return x.K; });

// group-into continuation
var pairs = from p in people
            group p.Name by p.Country into g
            where g.Values.Count() > 1
            select { Country = g.Key, Names = g.Values };

// a callback given to a pipeline
var limit = 3;
var big = arr.Where(Function(x) { return x > limit; }).ToArray();

// a rule passed to a generic routine
Function Apply(f, v) { return f(v); }
var doubled = Apply(Function(x) { return x * 2; }, 21);

// a function that answers with a function
var adder = Function(n) { return Function(x) { return x + n; }; };
var add10 = adder(10);
add10(7);   // 17

