var text = "{""number"":""A-17"",""lines"":[{""item"":""x"",""qty"":2}]}";

// the whole message
var reader = New JSONReader(text);
var order = reader.ReadValue();
Message(order.number + ": " + order.lines.Count());
foreach (line In order.lines) {
    Message(line.item + " x " + line.qty);
}

// ...or only a part of it
var walker = New JSONReader(text);
var lines = Undefined;
while (walker.Read()) {
    if (walker.CurrentValueType = JSONValueType.PropertyName And walker.CurrentValue = "lines") {
        lines = walker.ReadValue();
    }
}

// writing
var writer = New JSONWriter(JSONFormatting.Indented);
writer.WriteStartObject();
writer.WritePropertyName("number");  writer.WriteValue("A-17");
writer.WritePropertyName("lines");   writer.WriteValue(lines);      // an Array of Structures, whole
writer.WriteEndObject();
var result = writer.Close();

