    <fill from Source>
}

entries.example:
// the object module of the document being ENTERED (here: a receipt entered from an order)
Procedure Filling(Source, StandartProcessing)
{
    If (Not ValueIsFilled(Source)) {
        Return;                        // a plain new document: defaults only
    }
    // the header by name; the lines from what the order still has open
    Counterparty = Source.Counterparty;
    Warehouse = Source.Warehouse;
    foreach (line In Source.Goods) {
        var row = Goods.Add();
        row.Item = line.Item;
        row.Quantity = line.Quantity;
    }
}

// the same, asked from code
var doc = Documents.GoodsReceipt.CreateDocument();
