doc.Write();

// the catalog Units has ListOwner = Goods (set in metadata, not here)
var unit = Catalogs.Units.CreateElement();
unit.Owner = item;                 // required
unit.Description = "box of 12";
unit.Write();

// the units of one product
var units = From u In Data.Catalogs.Units Where u.Owner = item Select u;

